import java.io.*;
import java.util.*;

class MyWine implements IWine {

    // f1: the FIRST shortest brand among wines whose year is NOT a multiple of 3; none ⇒ "Not found"
    @Override
    public String f1(List<Wine> t) {
        Wine best = null;
        for (Wine w : t) {
            if (w.getYear() % 3 != 0) {
                if (best == null || w.getBrand().length() < best.getBrand().length()) {   // "<", not "<=": a tie keeps the earlier one
                    best = w;
                }
            }
        }
        return best == null ? "Not found" : best.getBrand();
    }

    // f2: a brand whose LENGTH is not prime becomes "PRE" + the first digit of the year
    @Override
    public void f2(List<Wine> t) {
        for (Wine w : t) {
            if (!isPrime(w.getBrand().length())) {
                w.setBrand("PRE" + String.valueOf(Math.abs(w.getYear())).charAt(0));   // year 12 ⇒ '1' (leftmost), not 12 % 10
            }
        }
    }

    // f3: smallest ODD year of the WHOLE list first; then remove brands starting with a lower-case letter AND having that year
    @Override
    public void f3(List<Wine> t) {
        Integer minOdd = null;
        for (Wine w : t) {
            if (w.getYear() % 2 != 0 && (minOdd == null || w.getYear() < minOdd)) {
                minOdd = w.getYear();
            }
        }
        if (minOdd == null) {
            return;                                          // no odd year: "do nothing"
        }
        Iterator<Wine> it = t.iterator();                    // remove through the iterator: in place, order kept, no exception
        while (it.hasNext()) {
            Wine w = it.next();
            String b = w.getBrand();
            if (!b.isEmpty() && Character.isLowerCase(b.charAt(0)) && w.getYear() == minOdd) {
                it.remove();
            }
        }
    }

    // helper of our own — the paper allows "other functions in MyWine"
    private boolean isPrime(int n) {
        if (n < 2) return false;
        for (int d = 2; d * d <= n; d++) {
            if (n % d == 0) return false;
        }
        return true;
    }
}

