import java.io.*;
import java.util.*;

// GIVEN as IWine.class — javap prints "public abstract java.lang.String f1(java.util.List<Wine>)": the <Wine> is real
interface IWine {
    public String f1(List<Wine> t);
    public void f2(List<Wine> t);
    public void f3(List<Wine> t);
}

